import { useMemo, useState } from 'react';
import { CheckCircle2, CircleAlert, Clock, HelpCircle, Search } from 'lucide-react';
import { api } from '../lib/api';
import type { ReliabilityNode, TripCheckResponse } from '../types';
import { PanelSkeleton } from './PanelStates';
import SourceNote from './SourceNote';

/**
 * Rider-facing "Will I make it?" (P5.5).
 *
 * One question, one honest answer: arriving on route A at a transfer stop,
 * will I catch route B? The verdict comes from the collector's observed
 * lateness (same model as the reliability map) and is deliberately hedged —
 * 'tight' outcomes name the miss probability; unmeasured pairs say so
 * instead of guessing.
 */

const VERDICT_STYLE: Record<
  NonNullable<TripCheckResponse['verdict']>,
  { icon: typeof CheckCircle2; color: string; label: string }
> = {
  likely: { icon: CheckCircle2, color: 'text-green-600', label: 'Likely' },
  tight: { icon: Clock, color: 'text-amber-600', label: 'Tight' },
  unlikely: { icon: CircleAlert, color: 'text-red-600', label: 'Unlikely' },
  unknown: { icon: HelpCircle, color: 'text-slate-500', label: 'Not enough data' },
};

export default function TripCheckPanel() {
  const [nodes, setNodes] = useState<ReliabilityNode[] | null>(null);
  const [nodesError, setNodesError] = useState<string | null>(null);
  const [stopId, setStopId] = useState('');
  const [routeArrive, setRouteArrive] = useState('');
  const [routeDepart, setRouteDepart] = useState('');
  const [slack, setSlack] = useState(0);
  const [result, setResult] = useState<TripCheckResponse | null>(null);
  const [checking, setChecking] = useState(false);

  // The reliability map is the source of transfer stops + their route pairs;
  // reusing it means the rider view can never offer a pair the map doesn't.
  useMemo(() => {
    api
      .measuredReliability()
      .then((r) => setNodes(r.nodes ?? []))
      .catch((e) => setNodesError(String(e)));
  }, []);

  const stop = useMemo(
    () => nodes?.find((n) => n.stop_id === stopId) ?? null,
    [nodes, stopId],
  );

  async function check() {
    if (!stopId || !routeArrive || !routeDepart) return;
    setChecking(true);
    setResult(null);
    try {
      setResult(await api.tripCheck(stopId, routeArrive, routeDepart, slack));
    } finally {
      setChecking(false);
    }
  }

  if (nodesError) {
    return (
      <div className="p-4 text-sm text-red-600">
        Reliability data unavailable: {nodesError}
      </div>
    );
  }
  if (nodes === null) return <PanelSkeleton label="Loading transfer stops…" />;

  return (
    <div className="space-y-3 p-4">
      <p className="text-sm text-slate-600">
        Pick a transfer stop and a route pair. The answer comes from{' '}
        <strong>observed</strong> bus departures — not promises — so it carries
        uncertainty and sometimes says "not enough data".
      </p>

      <label className="block text-xs font-medium text-slate-500">
        Transfer stop
        <select
          className="mt-1 w-full rounded border border-slate-300 p-2 text-sm"
          value={stopId}
          onChange={(e) => {
            setStopId(e.target.value);
            setRouteArrive('');
            setRouteDepart('');
            setResult(null);
          }}
        >
          <option value="">— choose a stop —</option>
          {nodes.map((n) => (
            <option key={n.stop_id} value={n.stop_id}>
              {n.stop_name} ({n.routes.length} routes)
            </option>
          ))}
        </select>
      </label>

      {stop && (
        <div className="grid grid-cols-2 gap-2">
          <label className="block text-xs font-medium text-slate-500">
            Arriving on
            <select
              className="mt-1 w-full rounded border border-slate-300 p-2 text-sm"
              value={routeArrive}
              onChange={(e) => setRouteArrive(e.target.value)}
            >
              <option value="">— route —</option>
              {stop.routes.map((r) => (
                <option key={r} value={r}>{r}</option>
              ))}
            </select>
          </label>
          <label className="block text-xs font-medium text-slate-500">
            Catching
            <select
              className="mt-1 w-full rounded border border-slate-300 p-2 text-sm"
              value={routeDepart}
              onChange={(e) => setRouteDepart(e.target.value)}
            >
              <option value="">— route —</option>
              {stop.routes.map((r) => (
                <option key={r} value={r}>{r}</option>
              ))}
            </select>
          </label>
        </div>
      )}

      <label className="block text-xs font-medium text-slate-500">
        Extra minutes you planned beyond the schedule ({slack})
        <input
          type="range" min={0} max={10} step={1} value={slack}
          onChange={(e) => setSlack(Number(e.target.value))}
          className="w-full"
        />
      </label>

      <button
        className="flex w-full items-center justify-center gap-2 rounded bg-sky-700 p-2 text-sm font-medium text-white disabled:opacity-40"
        disabled={!stopId || !routeArrive || !routeDepart || checking}
        onClick={check}
      >
        <Search size={14} /> {checking ? 'Checking…' : 'Check connection'}
      </button>

      {result && (
        <div className="rounded border border-slate-200 p-3">
          {result.found ? (
            <>
              <div className={`flex items-center gap-2 font-semibold ${VERDICT_STYLE[result.verdict ?? 'unknown'].color}`}>
                {(() => {
                  const V = VERDICT_STYLE[result.verdict ?? 'unknown'].icon;
                  return <V size={18} />;
                })()}
                {VERDICT_STYLE[result.verdict ?? 'unknown'].label}
                {result.measured && result.p_miss != null && (
                  <span className="ml-auto text-xs font-normal text-slate-500">
                    miss risk {(result.p_miss * 100).toFixed(0)}%
                  </span>
                )}
              </div>
              <p className="mt-2 text-sm text-slate-700">{result.message}</p>
              {result.measured && (
                <dl className="mt-2 grid grid-cols-3 gap-2 text-center text-xs text-slate-500">
                  <div>
                    <dt className="font-medium text-slate-700">{result.scheduled_wait_min}</dt>
                    <dt>scheduled wait</dt>
                  </div>
                  <div>
                    <dt className="font-medium text-slate-700">{result.realized_median_wait_min}</dt>
                    <dt>typical wait</dt>
                  </div>
                  <div>
                    <dt className="font-medium text-slate-700">
                      {result.n_obs_arrive}+{result.n_obs_depart}
                    </dt>
                    <dt>obs (arr+dep)</dt>
                  </div>
                </dl>
              )}
            </>
          ) : (
            <p className="text-sm text-slate-600">{result.message}</p>
          )}
          <SourceNote
            source={`Measured from GTFS-RT observed departures; ${result.method ?? 'uncertainty is reported, never hidden'}.`}
          />
        </div>
      )}
    </div>
  );
}
